SELECT

FROM voice_asset
WHERE owner_user_id = #{userId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
  AND status = #{status}
  AND is_deleted = 0
ORDER BY create_time DESC

SELECT

FROM voice_asset
WHERE owner_user_id = #{userId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
  AND role = #{role}
  AND is_deleted = 0
ORDER BY create_time DESC

mapper.update:
UPDATE voice_asset
SET is_deleted = 1, deleted_at = #{deletedAt}
WHERE voice_asset_id = #{voiceAssetId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
  AND is_deleted = 0
